/** The read-only Look surface has its own camera; library cards never become
 * battlefield objects simply because their previews are dragged or inspected. */
export function workspacePopup(ctx){
 if(!ctx.prefs.workspaceOpen)return '';
 const snapshot=ctx.ui.lastWorkspace,w=ctx.g.state.lookWorkspace,label=w?.label||'Look';
 const title=label==='Look at library'?'Look':label;
 const caption=`<div class="workspace-caption"><span>${h(snapshot?.source||'Cards from the resolving effect')}</span><small>${snapshot?.ids?.length||0} card${snapshot?.ids?.length===1?'':'s'} · ${h(w?.visibility||'private')} look</small></div>`;
 const controls=button('−','zoom-view','data-zone="workspace" data-scale="0.8333333333" title="Zoom out" aria-label="Zoom out Look"')+button('+','zoom-view','data-zone="workspace" data-scale="1.2" title="Zoom in" aria-label="Zoom in Look"')+tool('arrange','arrange','data-zone="workspace" title="Refresh Look grid"')+tool('close','close-workspace','title="Hide Look (does not cancel the effect)" aria-label="Hide Look"');
 return floating('workspace',title,caption+surfaceHTML(ctx,'workspace',ctx.ui.layouts.workspace||[]),controls,'workspace-window')
  .replace('data-floating="workspace"','data-floating="workspace" data-resizable="true"')
  .replace('</section>','<div class="popup-resize" data-resize-popup="workspace" title="Resize Look window" role="separator" aria-label="Resize Look window" tabindex="0"></div></section>');
}
